        return color;
    }
}

public class Program {
    public static void main(String[] args) {        
        //color 被初始化为 "Red"
        Vehicle v1 = new Vehicle();

        //color 被初始化为 "Green"
        Vehicle v2 = new Vehicle("Green"); 

        System.out.println(v2.getColor());
    }
}

